"""
    Parse a file path into components

    :param input_file_path:
    :return:
    """
def parse_file_path(input_file_path: Any) -> object {
    import os;
    (dirname, basename) = os.path.split(input_file_path);
    (`root, ext) = os.path.splitext(basename);
    return (dirname, basename, `root, ext);
}

"""Validate if field 300 should be excluded."""
def is_excluded(value: Any) -> object {
    exclude = [
        "mul. p",
        "mult p",
        "mult. p",
        "mult. p.",
        "mult. p",
        "multi p",
        "multi pages"
    ];
    if (not value or (value.strip().lower() in exclude)) {
        return True;
    }
    return False;
}

"""flatten
    flatten 2d array to 1d array
    :param x: initial array
    :return: array after flatten
    """
def flatten(x: Any) -> object {
    x_flatten = [];
    for i in range(len(x)) {
        for j in range(len(x[0])) {
            x_flatten.append(x[i][j]);
        }
    }
    return x_flatten;
}

"""Print out a dashed line

        To be used as visual boundaries for tests.

        Args:
            length (int): number of charters
            symbol (str): symbol to be used in the dashed line
                default: "="

        Returns:
            a string of characters of length `n`.
    """
def dashed_line(length: int, symbol: str = "=") -> str {
    def aux(length: Any, accum: Any) -> object {
        if (length == 0) {
            return accum;
        } else {
            return aux((length - 1), (accum + symbol));
        }
    }
    return aux(length, "");
}

