"""
    Bellman ford shortest path algorithm

    Parameters
    ----------
    nodes : set
            names of all nodes in the graph
    edges : list
            list of dependencies between nodes in the graph
            [(node1, node2, weight), ...]
    source : str
            name of source node

    Returns
    -------
    out : (bool, dict)
          (has_cycle, distances) has_cycle var check if cycle in the graph
          distance dict show len from source node to all nodes in the graph

    """
def bellman_ford(nodes: Any, edges: Any, source: Any) -> object {
    distances = {`node: float('Inf') for `node in nodes};
    distances[source] = 0;
    for _ in range(1, len(nodes)) {
        for (src, dest, weight) in edges {
            if (distances[dest] > (distances[src] + weight)) {
                distances[dest] = distances[src] + weight;
            }
        }
    }
    has_cycle = False;
    for (src, dest, weight) in edges {
        if (distances[dest] > (distances[src] + weight)) {
            has_cycle = True;
        }
    }
    return (has_cycle, distances);
}

"""
    construct a Jekyll yaml collection (a dictionary) from a menu dict
    example input:  {'ReadingNotes': ['Book_NeuralNetworksAndDeepLearning', 'test']}
    example output:  {'ReadingNotes_Book_NeuralNetworksAndDeepLearning': {'output': True,
    'permalink': '/ReadingNotes/Book_NeuralNetworksAndDeepLearning/:path'},
    'ReadingNotes_test': {'output': True, 'permalink': '/ReadingNotes/test/:path'}}
    """
def collections_from_dict(dic: Any) -> object {
    collection = {};
    for (k, v) in dic.items() {
        menu_name_en = k;
        for collection_directory in v {
            menu_iterm = 'collection_' + menu_name_en + '_' + collection_directory;
            permalink = '/{0}/{1}/:path'.format(menu_name_en, collection_directory);
            collection[menu_iterm] = {'output': True, 'permalink': permalink};
        }
    }
    return collection;
}

